const RASSINI_LOGO = 'data:image/png;base64,';
const RASSINI_FAVICON = 'data:image/png;base64,';

function loadFavicon() {
    let link = document.querySelector("link[rel='icon']");
    if (!link) {
        link = document.createElement('link');
        link.rel = 'icon';
        document.head.appendChild(link);
    }
    link.href = RASSINI_FAVICON;
}

const RASSINI_GLOBAL_STYLES = `

:root {

    --surface-ground: #f3f4f6;

    --surface-card: #ffffff;

    --text-color: #616166;

    --card-shadow: 0 4px 20px rgba(0, 0, 0, .08);

}

html {

    height: 100%;

    font-size: 14px;

    line-height: 1.2;

}

body {

    font-family: 'Trebuchet MS', sans-serif;

    color: var(--text-color);

    background-color: var(--surface-ground);

    margin: 0;

    padding: 0;

    min-height: 100%;

    -webkit-font-smoothing: antialiased;

    -moz-osx-font-smoothing: grayscale;

}

a {

    text-decoration: none;

}

.layout-wrapper {

    min-height: 100vh;

}

.layout-main {

    flex: 1 1 auto;

    padding-bottom: 2rem;

}

`;

function loadPrimeIcons() {
    const id = 'rassini-primeicons';
    if (document.getElementById(id)) {
        return;
    }
    const link = document.createElement('link');
    link.id = id;
    link.rel = 'stylesheet';
    link.href =
        'https://unpkg.com/primeicons@7.0.0/primeicons.css';
    document.head.appendChild(link);
}

function loadPrimeFlex() {
    const id = 'rassini-primeflex';
    if (document.getElementById(id)) {
        return;
    }
    const link = document.createElement('link');
    link.id = id;
    link.rel = 'stylesheet';
    link.href =
        'https://unpkg.com/primeflex@4.0.0/primeflex.css';
    document.head.appendChild(link);
}

function provideRassiniTheme() {
    loadFavicon();
    loadPrimeIcons();
    loadPrimeFlex();
    const styleId = 'rassini-global-theme';
    if (!document.getElementById(styleId)) {
        const style = document.createElement('style');
        style.id = styleId;
        style.innerHTML =
            RASSINI_GLOBAL_STYLES;
        document.head.appendChild(style);
    }
    return makeEnvironmentProviders([
        providePrimeNG({
            theme: {
                preset: RassiniPreset,
                options: {
                    darkModeSelector: '.app-dark'
                }
            }
        }),
        MessageService,
        ConfirmationService
    ]);
}

